<template><section v-if="data" class="space-y-6"><CCard><div class="hotel-intro"><img :src="data.hotel.cover_image || '/images/room-placeholder.svg'" :alt="data.hotel.cover_image ? 'Presentación del hotel' : 'Ilustración de una habitación de ejemplo'" class="hotel-cover" loading="lazy"><div class="space-y-3"><p v-if="data.hotel.cover_image==='/images/demo-bedroom.webp'" class="demo-image-note">Imagen generada para la demo · Personalizable</p><h2>{{ data.hotel.hotel_name }}</h2><p>{{ data.hotel.description || 'Un espacio para descansar y disfrutar tu próxima estancia.' }}</p><p v-if="data.hotel.address || data.hotel.city">{{ data.hotel.address }} {{ data.hotel.city }}</p><p v-if="data.hotel.phone">Teléfono: {{ data.hotel.phone }}</p><p v-if="data.hotel.email">Correo: {{ data.hotel.email }}</p></div></div></CCard><div class="hotel-room-grid"><article v-for="r in data.rooms" :key="r.id" class="hotel-room"><img :src="r.image_url || '/images/room-placeholder.svg'" :alt="r.image_url ? r.name : `Ilustración de ejemplo para ${r.name}`" loading="lazy"><div><h3>{{ r.name }}</h3><p>{{ r.description || 'Comodidad y descanso para tu viaje.' }}</p><p>Hasta {{ r.capacity }} personas · {{ hotel.money(r.price) }} / noche</p></div></article></div></section><p v-if="error" class="operation-error" role="alert">No se pudo cargar la presentación del hotel. <button class="underline" @click="load">Reintentar</button></p></template>
<script setup lang="ts">
import {useApiClient} from '~/services/api'
import type {ApiResponse} from '~/types'
import type {Presentation} from '~/types/guestServices'
const emit=defineEmits<{loaded:[presentation:Presentation]}>()
const api=useApiClient(),hotel=useHotelSettings(),data=ref<Presentation>(),error=ref(false)
const load=async()=>{error.value=false;try{data.value=(await api.request<ApiResponse<Presentation>>('/portal/presentation')).data;if(data.value)emit('loaded',data.value)}catch{error.value=true}}
onMounted(load)
</script>
<style scoped>.hotel-intro{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:28px;align-items:center}.hotel-cover{width:100%;aspect-ratio:16/10;object-fit:cover;border-radius:10px}.hotel-intro h2{font-size:22px}.hotel-intro p,.hotel-room p{font-size:13px;color:var(--text-secondary);line-height:1.8}.hotel-room-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.hotel-room{border:1px solid var(--border-color);background:var(--bg-secondary);border-radius:12px;overflow:hidden}.hotel-room img{width:100%;aspect-ratio:16/10;object-fit:cover}.hotel-room>div{padding:20px}.hotel-room h3{margin-bottom:8px;font-weight:500}@media(max-width:700px){.hotel-intro{grid-template-columns:1fr}.hotel-room-grid{grid-template-columns:1fr}}.hotel-room-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.hotel-room{display:grid;grid-template-columns:140px minmax(0,1fr);align-items:center;border-radius:14px}.hotel-room img{height:100%;min-height:180px;aspect-ratio:auto}.hotel-room>div{padding:22px}.hotel-room h3{font-size:16px;font-weight:600}.hotel-room p{font-size:12px;line-height:1.7}.hotel-intro{gap:32px}.hotel-intro h2{font-size:25px;letter-spacing:-.6px}.hotel-cover{border-radius:14px}
@media(max-width:760px){.hotel-room-grid{grid-template-columns:1fr}}
@media(max-width:420px){.hotel-room{grid-template-columns:100px minmax(0,1fr)}.hotel-room>div{padding:16px}.hotel-room img{min-height:160px}}</style>
